module gcd_split (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] arr_0,\n    input wire [7:0] arr_1,\n    input wire [7:0] arr_2,\n    input wire [7:0] arr_3,\n    input wire [7:0] arr_4,\n    input wire [7:0] arr_5,\n    input wire [7:0] arr_6,\n    input wire [7:0] arr_7,\n    output reg done,\n    output reg result,\n    output reg [7:0] assignment\n);\n\n    // State declarations\n    localparam [1:0] IDLE     = 2'd0;\n    localparam [1:0] COMPUTE  = 2'd1;\n    localparam [1:0] CHECK    = 2'd2;\n    localparam [1:0] FINISHED = 2'd3;\n    \n    reg [1:0] state;\n    reg [7:0] mask;\n    reg [7:0] gcd1, gcd2;\n    reg [7:0] mask_count;\n    \n    // Input storage array\n    reg [7:0] arr_reg_0;\n    reg [7:0] arr_reg_1;\n    reg [7:0] arr_reg_2;\n    reg [7:0] arr_reg_3;\n    reg [7:0] arr_reg_4;\n    reg [7:0] arr_reg_5;\n    reg [7:0] arr_reg_6;\n    reg [7:0] arr_reg_7;\n    \n    // Iterative GCD function\n    function automatic [7:0] gcd_iter;\n        input [7:0] a;\n        input [7:0] b;\n        reg [7:0] aa, bb, temp;\n        begin\n            aa = a;\n            bb = b;\n            while (bb != 0) begin\n                temp = aa % bb;\n                aa = bb;\n                bb = temp;\n            end\n            gcd_iter = aa;\n        end\n    endfunction\n    \n    // Combinational group calculation\n    reg [7:0] comb_gcd1, comb_gcd2;\n    reg [7:0] comb_count1, comb_count2;\n    integer comb_i;\n    \n    always @(*) begin\n        comb_gcd1 = 8'd0;\n        comb_gcd2 = 8'd0;\n        comb_count1 = 8'd0;\n        comb_count2 = 8'd0;\n        \n        // Group 1 (mask=1)\n        for (comb_i = 0; comb_i < 8; comb_i = comb_i + 1) begin\n            if (mask[comb_i]) begin\n                comb_count1 = comb_count1 + 8'd1;\n                if (comb_count1 == 8'd1) begin\n                    comb_gcd1 = (comb_i == 0) ? arr_reg_0 :\n                                (comb_i == 1) ? arr_reg_1 :\n                                (comb_i == 2) ? arr_reg_2 :\n                                (comb_i == 3) ? arr_reg_3 :\n                                (comb_i == 4) ? arr_reg_4 :\n                                (comb_i == 5) ? arr_reg_5 :\n                                (comb_i == 6) ? arr_reg_6 :\n                                arr_reg_7;\n                end\n                else begin\n                    comb_gcd1 = gcd_iter(comb_gcd1, \n                                (comb_i == 0) ? arr_reg_0 :\n                                (comb_i == 1) ? arr_reg_1 :\n                                (comb_i == 2) ? arr_reg_2 :\n                                (comb_i == 3) ? arr_reg_3 :\n                                (comb_i == 4) ? arr_reg_4 :\n                                (comb_i == 5) ? arr_reg_5 :\n                                (comb_i == 6) ? arr_reg_6 :\n                                arr_reg_7);\n                end\n            end\n        end\n        \n        // Group 2 (mask=0)\n        for (comb_i = 0; comb_i < 8; comb_i = comb_i + 1) begin\n            if (!mask[comb_i]) begin\n                comb_count2 = comb_count2 + 8'd1;\n                if (comb_count2 == 8'd1) begin\n                    comb_gcd2 = (comb_i == 0) ? arr_reg_0 :\n                                (comb_i == 1) ? arr_reg_1 :\n                                (comb_i == 2) ? arr_reg_2 :\n                                (comb_i == 3) ? arr_reg_3 :\n                                (comb_i == 4) ? arr_reg_4 :\n                                (comb_i == 5) ? arr_reg_5 :\n                                (comb_i == 6) ? arr_reg_6 :\n                                arr_reg_7;\n                end\n                else begin\n                    comb_gcd2 = gcd_iter(comb_gcd2, \n                                (comb_i == 0) ? arr_reg_0 :\n                                (comb_i == 1) ? arr_reg_1 :\n                                (comb_i == 2) ? arr_reg_2 :\n                                (comb_i == 3) ? arr_reg_3 :\n                                (comb_i == 4) ? arr_reg_4 :\n                                (comb_i == 5) ? arr_reg_5 :\n                                (comb_i == 6) ? arr_reg_6 :\n                                arr_reg_7);\n                end\n            end\n        end\n    end\n    \n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        integer i;\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 1'b0;\n            assignment <= 8'b0;\n            mask <= 8'b0;\n            gcd1 <= 8'b0;\n            gcd2 <= 8'b0;\n            mask_count <= 8'b0;\n            arr_reg_0 <= 8'b0;\n            arr_reg_1 <= 8'b0;\n            arr_reg_2 <= 8'b0;\n            arr_reg_3 <= 8'b0;\n            arr_reg_4 <= 8'b0;\n            arr_reg_5 <= 8'b0;\n            arr_reg_6 <= 8'b0;\n            arr_reg_7 <= 8'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Capture inputs\n                        {arr_reg_7, arr_reg_6, arr_reg_5, arr_reg_4, arr_reg_3, arr_reg_2, arr_reg_1, arr_reg_0} <= \n                            {arr_7, arr_6, arr_5, arr_4, arr_3, arr_2, arr_1, arr_0};\n                        mask <= 8'b00000001;\n                        mask_count <= 8'd1;\n                        state <= COMPUTE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    gcd1 <= comb_gcd1;\n                    gcd2 <= comb_gcd2;\n                    state <= CHECK;\n                end\n                \n                CHECK: begin\n                    if (comb_count1 > 0 && comb_count2 > 0 && gcd1 == 8'd1 && gcd2 == 8'd1) begin\n                        result <= 1'b1;\n                        assignment <= mask;\n                        state <= FINISHED;\n                    end else begin\n                        if (mask_count >= 8'd254) begin\n                            result <= 1'b0;\n                            assignment <= 8'b0;\n                            state <= FINISHED;\n                        end else begin\n                            mask <= mask + 8'b1;\n                            mask_count <= mask_count + 8'd1;\n                            state <= COMPUTE;\n                            if (mask + 8'b1 == 8'b11111111) begin\n                                mask <= 8'b00000001;\n                            end\n                        end\n                    end\n                end\n                \n                FINISHED: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule